package org.jeecg.modules.packagemanagement;

import com.alibaba.fastjson2.JSONObject;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.*;
import org.jeecg.modules.packagemanagement.application.apps.*;
import org.jeecg.modules.packagemanagement.application.apps.impl.ClientServiceImpl;
import org.jeecg.modules.packagemanagement.application.legacy.*;
import org.jeecg.modules.packagemanagement.application.port.*;
import org.jeecg.modules.packagemanagement.config.PackageManagementProperties;
import org.jeecg.modules.packagemanagement.domain.app.AppManager;
import java.time.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.jeecg.modules.packagemanagement.PackageBusinessTest.inject;

class PackageProtocolTest {
 private ClientServiceImpl service;private IAppManagerService apps;private GeoPort geo;private AppLogPort logs;private AppManager app;
 private static final long NOW=1700000000000L;
 @BeforeEach void setup(){service=new ClientServiceImpl();apps=mock(IAppManagerService.class);geo=mock(GeoPort.class);logs=mock(AppLogPort.class);inject(service,"appRepository",apps);inject(service,"geo",geo);inject(service,"esAppLogRepository",logs);inject(service,"clock",Clock.fixed(Instant.ofEpochMilli(NOW),ZoneId.of("Asia/Shanghai")));PackageManagementProperties settings=new PackageManagementProperties();settings.setDefaultAesKey("1234567890123456");inject(service,"settings",settings);when(geo.getIpAddress(any())).thenReturn("192.0.2.1");when(geo.getCityByIp(any())).thenReturn("中国");when(geo.getCountryAndCountryCodeByIP(any())).thenReturn(Map.of("country","中国","countryCode","cn","status","false"));app=new AppManager();app.setPackageCode("com.test");app.setStatus(1);app.setWhetherUs(0);app.setWhetherRestrict(0);app.setWhetherUse(1);app.setUrl("https://example.invalid/play?x=1");app.setMark("memo");app.setAreas("中国");app.setAppName("Test");when(apps.selectAppManagerByPackageName("com.test")).thenReturn(app);}
 private MockHttpServletRequest request(String... pairs){MockHttpServletRequest r=new MockHttpServletRequest("GET","/api");for(int i=0;i<pairs.length;i+=2)r.setParameter(pairs[i],pairs[i+1]);return r;}
 private Map<?,?> map(Object value){return (Map<?,?>)value;}
 private String b64(String value){return Base64.getEncoder().encodeToString(value.getBytes(StandardCharsets.UTF_8));}
 private JSONObject decoded(Object value,boolean suffix){String text=(String)value;if(suffix)text=text.substring(0,text.length()-"comtest".length());return JSONObject.parseObject(new String(Base64.getDecoder().decode(text),StandardCharsets.UTF_8));}
 @Test void apiMissingMalformedUnknownAndDisabled(){assertEquals(0,map(service.api(request())).get("status"));assertEquals(0,map(service.api(request("id","%%%"))).get("status"));assertEquals(0,map(service.api(request("id",b64("none")))).get("status"));app.setStatus(0);assertEquals(0,map(service.api(request("id",b64("com.test")))).get("status"));}
 @Test void apiUsAndSingleMultiWhitelistPreserveAfEncoding(){app.setWhetherUs(1);when(geo.getCityByIp(any())).thenReturn("美国");assertEquals(0,map(service.api(request("id",b64("com.test")))).get("status"));app.setWhetherUs(0);app.setWhetherRestrict(1);app.setAreas("中国");assertEquals(0,map(service.api(request("id",b64("com.test")))).get("status"));app.setAreas("中国,美国");Map<?,?> result=map(service.api(request("id",b64("com.test"),"af_id","abc")));assertEquals(1,result.get("status"));assertEquals(b64(app.getUrl()+"&appsflyer_id=abc"),result.get("url"));app.setAreas("美国");assertEquals(1,map(service.api(request("id",b64("com.test")))).get("status"));}
 @Test void loginDefaultAndActiveFields(){assertEquals(-1,map(service.login(request())).get("code"));Map<?,?> result=map(service.login(request("username","com.test","password","af")));assertEquals(1,result.get("code"));assertEquals("request was successful",result.get("message"));assertEquals(Map.of("show",1,"path",app.getUrl()+"&appsflyer_id=af","useAF",1),result.get("data"));app.setStatus(0);assertEquals(-1,map(service.login(request("username","com.test"))).get("code"));}
 @Test void redirectHasLegacyStatusLocationAndAfSwitch(){MockHttpServletResponse response=new MockHttpServletResponse();service.redirected(request(),response);assertEquals(302,response.getStatus());assertEquals("about:blank",response.getRedirectedUrl());response=new MockHttpServletResponse();service.redirected(request("packName","com.test","af_id","af"),response);assertEquals(app.getUrl()+"&appsflyer_id=af",response.getRedirectedUrl());app.setWhetherUse(0);response=new MockHttpServletResponse();service.redirected(request("packName","com.test","af_id","af"),response);assertEquals(app.getUrl(),response.getRedirectedUrl());}
 @Test void bannerUsesSystemNameAndSystemId(){assertEquals("",service.getBanner(request()));assertEquals(app.getUrl()+"&appsflyer_id=af",service.getBanner(request("systemName","com.test","systemID","af")));}
 @Test void checkUrlUsesHeaderSelectedParameterNames(){var missing=request();missing.addHeader("tokenID","customPackage");missing.addHeader("baseTime","customToken");assertEquals(Map.of("event",false,"canLoad",false,"canAppend",false,"load",""),service.checkUrl(missing));var r=request("customPackage","com.test","customToken","af");r.addHeader("tokenID","customPackage");r.addHeader("baseTime","customToken");Map<?,?> result=map(service.checkUrl(r));assertEquals(true,result.get("event"));assertEquals(true,result.get("canLoad"));assertEquals(true,result.get("canAppend"));assertEquals("af",result.get("token"));assertEquals(app.getUrl()+"&appsflyer_id=af",result.get("load"));}
 @Test void dynamicDefaultAndConfiguredFields(){assertEquals(Map.of("app_id","","app_cache",0,"app_limit","","app_name","","app_dynamic",""),service.dynamicAdj(request()));assertEquals(Map.of("app_id","com.test","app_cache",1,"app_limit",app.getUrl(),"app_name","Test","app_dynamic","memo"),service.dynamicAdj(request("id","com.test")));}
 @Test void userInfoTimestampDigestAndUserAgent(){var r=request("user_id","com.test","user_token","af");r.addHeader("User-Agent","agent-test");Map<?,?> result=map(service.getUserInfo(r));assertEquals(NOW-65535L,result.get("timestamp"));assertEquals(cn.hutool.crypto.digest.DigestUtil.md5Hex(String.valueOf(NOW)),result.get("token"));assertEquals("agent-test",result.get("ty"));assertEquals(app.getUrl()+"&appsflyer_id=af",result.get("imgs"));assertEquals(1,result.get("isApp"));assertEquals("中国",result.get("user"));assertEquals("memo",result.get("user_info"));}
 @Test void base64DataMissingMalformedSimGateAndEncodedConfiguration(){assertNull(service.base64Data(request()));assertNull(service.base64Data(request("pack_a","com.test","data_a","{\"sim_a\":\"123\"}")));JSONObject result=decoded(service.base64Data(request("pack_a","com.test","data_a","bad-json")),true);assertEquals(1,result.getIntValue("s_coe"));assertEquals(app.getUrl(),result.getString("link_oth"));assertEquals(1,result.getIntValue("by_me"));}
 @Test void base64DataTwoUsesFixedTimestampAndShanghaiString(){assertNull(service.base64Data2(request()));JSONObject result=decoded(service.base64Data2(request("index","com.test")),true);assertEquals(1,result.getIntValue("total_pages"));assertEquals(app.getUrl(),result.getString("list_details"));assertEquals("JSON",result.getString("data_type"));assertEquals(b64(String.valueOf(NOW)),result.getString("group"));assertEquals(NOW,result.getLongValue("isNow"));assertEquals("2023-11-15 06:13:20",result.getString("date_time"));}
 @Test void base64DataThreeAddsCountryCodeAndPreservesFields(){assertNull(service.base64Data3(request()));app.setUrl("{\"url\":\"https://example.invalid\"}");JSONObject result=decoded(service.base64Data3(request("timestamp","com.test")),false);assertEquals(1,result.getIntValue("pid"));assertEquals(1,result.getIntValue("spid"));assertEquals("memo",result.getString("mark"));assertEquals("cn",JSONObject.parseObject(result.getString("origin")).getString("cityCode"));}
 @Test void appOneUsesFirstDottedValueAndConfiguredDefaultThenAppNameKey()throws Exception{assertNull(service.app1(request()));app.setAppName("");var r=request("anything","com.test");String encrypted=(String)service.app1(r);JSONObject result=JSONObject.parseObject(AESUtils.decrypt(encrypted,"1234567890123456"));assertEquals(1,result.getIntValue("code"));assertEquals(app.getUrl(),result.getString("data"));app.setAppName("abcdefghijklmnop");assertEquals(result,JSONObject.parseObject(AESUtils.decrypt((String)service.app1(r),"abcdefghijklmnop")));LinkedHashMap<String,String[]> values=new LinkedHashMap<>();values.put("one",new String[]{"nondotted","com.first"});values.put("two",new String[]{"com.second"});assertEquals("com.first",ParamsUtils.getParams(values));}
}
